import { daysBetween } from "@/lib/dates";
import { EXTENSION_DEADLINE } from "@/lib/tax-year";

/** Days left until the Oct 15 extension deadline. */
export function extensionDaysLeft(asOf: Date = new Date()): number {
  return daysBetween(EXTENSION_DEADLINE, asOf);
}

import Link from "next/link";
import { EmptyState } from "@/components/empty-state";
import { PageHeader } from "@/components/page-header";
import { ReturnStatusBadge } from "@/components/status-badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { getRejectedReturns } from "@/lib/data";
import { formatDate } from "@/lib/dates";
import { extensionDaysLeft } from "@/lib/extension-pace";
import { rejectDetail } from "@/lib/rejects";

export const metadata = {
  title: "E-file rejects",
};

export const dynamic = "force-dynamic";

export default async function RejectsPage() {
  const rejected = await getRejectedReturns();
  const daysLeft = extensionDaysLeft();

  return (
    <div className="mx-auto flex max-w-6xl flex-col gap-6">
      <PageHeader
        eyebrow="E-file"
        title="Rejected returns"
        description="IRS acknowledgments that came back rejected. Each one needs a fix and a resubmit before the Oct 15 extension deadline."
      />

      {rejected.length === 0 ? (
        <EmptyState
          title="No rejected returns"
          body="Every transmitted return was accepted or is still waiting on an acknowledgment."
          imageSrc="/images/empty-returns.svg"
          imageAlt="Empty return folder illustration"
          action={
            <Button asChild variant="outline" size="sm">
              <Link href="/returns">All returns</Link>
            </Button>
          }
        />
      ) : (
        <div className="grid gap-3">
          {rejected.map((taxReturn) => {
            const detail = taxReturn.rejectCode ? rejectDetail(taxReturn.rejectCode) : null;
            return (
              <Link key={taxReturn.id} href={`/returns/${taxReturn.id}`}>
                <Card className="transition-colors hover:bg-accent/40">
                  <CardContent className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
                    <div className="min-w-0 space-y-1">
                      <p className="font-medium">{taxReturn.filer.name}</p>
                      <p className="font-mono text-xs text-muted-foreground">
                        {taxReturn.number} · {taxReturn.rejectCode} ·{" "}
                        {taxReturn.rejectedOn ? `rejected ${formatDate(taxReturn.rejectedOn)}` : "rejected"}
                      </p>
                      {detail ? (
                        <>
                          <p className="text-sm">{detail.summary}</p>
                          <p className="text-sm text-muted-foreground">{detail.fix}</p>
                        </>
                      ) : null}
                    </div>
                    <div className="flex shrink-0 items-center gap-3">
                      <p className="text-sm font-medium text-muted-foreground">
                        {daysLeft} {daysLeft === 1 ? "day" : "days"} left
                      </p>
                      <ReturnStatusBadge status="REJECTED" />
                    </div>
                  </CardContent>
                </Card>
              </Link>
            );
          })}
        </div>
      )}
    </div>
  );
}

import { demoDay } from "@/lib/clock";

/**
 * Tax year 2025 figures this console uses. Read limits and deadlines from here;
 * never type one inline. Amounts are integer cents.
 */
export const TAX_YEAR = 2025;

export const FILING_DEADLINE = demoDay("2026-04-15");
export const EXTENSION_DEADLINE = demoDay("2026-10-15");

export const EDUCATION_CREDITS = ["AOTC", "LLC"] as const;
export type EducationCredit = (typeof EDUCATION_CREDITS)[number];

export const EDUCATION_CREDIT_LABEL: Record<EducationCredit, string> = {
  AOTC: "American opportunity credit",
  LLC: "Lifetime learning credit",
};

/** AOTC: 100% of the first $2,000 and 25% of the next $2,000 of expenses, per student. */
export const AOTC_LIMITS = {
  fullRateExpenseCents: 200_000,
  partialRateExpenseCents: 200_000,
  partialRate: 0.25,
  maxCreditCents: 250_000,
} as const;

/** LLC: 20% of the first $10,000 of expenses, per return. */
export const LLC_LIMITS = {
  expenseCapCents: 1_000_000,
  rate: 0.2,
  maxCreditCents: 200_000,
} as const;

export const EDUCATION_CREDIT_MAX_CENTS: Record<EducationCredit, number> = {
  AOTC: AOTC_LIMITS.maxCreditCents,
  LLC: LLC_LIMITS.maxCreditCents,
};

export const EDUCATION_CREDIT_SCOPE: Record<EducationCredit, string> = {
  AOTC: "per student",
  LLC: "per return",
};

export function isEducationCredit(value: string): value is EducationCredit {
  return (EDUCATION_CREDITS as readonly string[]).includes(value);
}

export function educationCreditLabel(credit: string): string {
  if (!isEducationCredit(credit)) {
    throw new Error(`Unknown credit "${credit}". This console reviews AOTC and LLC only.`);
  }
  return EDUCATION_CREDIT_LABEL[credit];
}

export function formatDate(value: Date | string): string {
  const date = typeof value === "string" ? new Date(value) : value;
  return new Intl.DateTimeFormat("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric",
    timeZone: "UTC",
  }).format(date);
}

export function daysBetween(later: Date, earlier: Date): number {
  const ms = later.getTime() - earlier.getTime();
  return Math.round(ms / 86_400_000);
}

/** Frozen demo clock. Age returns against this, never Date.now(). */
export const DEMO_AS_OF = new Date("2026-10-08T12:00:00.000Z");

/** Last 30 days ending on the demo clock — matches the dashboard date chip. */
export const DEMO_WINDOW_START = new Date("2026-09-08T12:00:00.000Z");
export const DEMO_PRIOR_START = new Date("2026-08-09T12:00:00.000Z");
export const DEMO_PRIOR_END = new Date("2026-09-07T12:00:00.000Z");

export function demoDay(isoDate: string) {
  return new Date(`${isoDate}T12:00:00.000Z`);
}

